let History := Bool × Bool × Bool × Bool × Bool;
have edit := fun history =>
  if history.1 = true then (history.1, !history.2.1, history.2.2.1, history.2.2.2.1, history.2.2.2.2)
  else (history.1, history.2.1, !history.2.2.1, !history.2.2.2.1, !history.2.2.2.2);
have commitment := fun history => !history.2.1;
have balanceTarget := fun history => history.2.1;
have eventOrderTarget := fun history => history.2.2.1;
have identitySourceTarget := fun history => history.2.2.2.1;
have contractAuthorizationTarget := fun history => history.2.2.2.2;
have otherEdit := (false, false, false, false, false);
(∀ (history : History),
    commitment history = commitment (edit history) → balanceTarget history = balanceTarget (edit history)) ∧
  commitment otherEdit = commitment (edit otherEdit) ∧
    eventOrderTarget otherEdit ≠ eventOrderTarget (edit otherEdit) ∧
      identitySourceTarget otherEdit ≠ identitySourceTarget (edit otherEdit) ∧
        contractAuthorizationTarget otherEdit ≠ contractAuthorizationTarget (edit otherEdit) ∧
          ¬∀ (target : History → Bool) (history : History),
              commitment history = commitment (edit history) → target history = target (edit history)

have sameLaw := {pair | pair.1 = pair.2};
have differentLaw := {pair | pair.1 ≠ pair.2};
(Prod.snd '' sameLaw = Prod.fst '' sameLaw ∧
    Prod.fst '' sameLaw = Prod.fst '' differentLaw ∧ Prod.snd '' sameLaw = Prod.snd '' differentLaw) ∧
  ¬∃ state, (state.1, state.2.1) ∈ sameLaw ∧ (state.2.1, state.2.2) ∈ sameLaw ∧ (state.1, state.2.2) ∈ differentLaw

